      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O planejamento do embarque considera tipo da carga, peso, volume e forma, além das características e limitações da embarcação de apoio e de eventuais restrições operativas dos guindastes da unidade marítima.",
          "trechos": [
            "Ed5beadc7797d400c:692:1385"
          ],
          "condicoes": [
            "no contexto de operação portuária e suprimento a unidades marítimas",
